 "content": "def transform(grid):
    # Connect same-color endpoints across a one-cell gap only when their
    # intervening cell is the background color. The demo rule is ambiguous
    # for patterns outside horizontal rows; refine with further examples.
    out = [row[:] for row in grid]
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] != background and row[c - 1] == row[c + 1] and row[c] == background:
                out[r][c] = 2
    return out
